const RTSales=(()=>{
 let current=null,data=null;
 const signIn=()=>'/signin-with-chatgpt?return_to='+encodeURIComponent(location.pathname+location.search);
 async function api(body){const r=await fetch('/api/commerce',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),v=await r.json();if(!r.ok)throw Error(v.error);return v}
 function formDialog(title,html,submit){let d=document.getElementById('action-modal');if(!d){d=document.createElement('dialog');d.id='action-modal';document.body.append(d)}d.innerHTML=`<h2>${title}</h2><form>${html}<p class="form-error" role="status"></p><div class="row-actions"><button type="submit">保存 / Save</button><button type="button" data-cancel>取消</button></div></form>`;d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{await submit(new FormData(e.target));d.close()}catch(err){d.querySelector('.form-error').textContent=err.message;btn.disabled=false}};d.showModal();return d}
 const field=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0.01" step="0.01" max="1000000"':''} required></label>`;
 const note=(name,label,value='')=>`<label>${label}<textarea name="${name}" maxlength="5000">${esc(value)}</textarea></label>`;
 const cents=v=>{if(!/^\d+(\.\d{1,2})?$/.test(v))throw Error('金额最多两位小数');return Math.round(Number(v)*100)};
 async function mount(l){current=l;if(!RTCRM.canEdit){const host=$('panel-orders');if(host)host.innerHTML='<a href="'+signIn()+'" target="_top">登录查看订单 / Sign in to view orders</a>';return}try{const r=await fetch('/api/commerce?lead='+encodeURIComponent(l.id),{cache:'no-store'});const v=await r.json();if(!r.ok)throw Error(v.error);if(current.id!==l.id)return;data=v;draw()}catch(e){const host=$('panel-orders');if(host)host.textContent=e.message}}
 function draw(){const h=$('panel-orders');if(!h||!data)return;h.innerHTML=`<div class="sales-tools"><button id="new-order">Make an Order</button><button id="new-payment">Make a Payment</button><button id="invoice-settings">发票设置</button><button id="invoice-sample">预览发票模板</button></div><p class="muted">付款为手工记账，不会发起扣款。</p>${data.orders.map(o=>{const paid=data.payments.filter(p=>p.order_id===o.id).reduce((s,p)=>s+p.amount,0),inv=data.invoices.find(i=>i.order_id===o.id);return `<details class="order-card"><summary><strong>${esc(o.description)}</strong><span>${RTInvoice.money(o.amount)}</span></summary><p>${esc(o.buyer)}</p><p class="preserve-lines">${esc(o.notes)}</p><p>已记录付款：${RTInvoice.money(paid)}</p><button data-pay="${esc(o.id)}">Make a Payment</button><button data-issue="${esc(o.id)}">${inv?'下载发票 RT-'+String(inv.number).padStart(6,'0'):'Issue Invoice'}</button><div>${data.payments.filter(p=>p.order_id===o.id).map(p=>`<p>${esc(p.date)} · ${RTInvoice.money(p.amount)} · ${esc(p.reference)}<small>${esc(p.notes)}</small></p>`).join('')}</div></details>`}).join('')||'<p>暂无订单</p>'}<p id="sales-message" role="status"></p>`;
 $('new-order').onclick=()=>order();$('new-payment').onclick=()=>payment();$('invoice-settings').onclick=settings;$('invoice-sample').onclick=sample;h.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>payment(b.dataset.pay));h.querySelectorAll('[data-issue]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await issue(b.dataset.issue);await mount(current)}catch(e){if($('sales-message'))$('sales-message').textContent=e.message;else alert(e.message);b.disabled=false}})}
 function order(){if(!RTCRM.canEdit){location.href=signIn();return}const id=crypto.randomUUID();formDialog('Make an Order',field('amount','金额 AUD（按发票设置处理 GST）','','number')+field('description','订单内容')+field('buyer','客户抬头',current.name)+note('notes','订单备注（内部记录）'),async f=>{await api({operation:'order',id,leadId:current.id,amount:cents(f.get('amount')),description:f.get('description'),buyer:f.get('buyer'),notes:f.get('notes')});await mount(current)})}
 function payment(orderId){if(!data?.orders.length){alert('请先创建订单，再记录对应付款。');return}const id=crypto.randomUUID();formDialog('Make a Payment · 记录已收款',`<label>对应订单<select name="orderId">${data.orders.map(o=>`<option value="${esc(o.id)}" ${o.id===orderId?'selected':''}>${esc(o.description)} · ${RTInvoice.money(o.amount)}</option>`).join('')}</select></label>`+field('amount','实收金额 AUD','','number')+field('date','收款日期',new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Melbourne'}), 'date')+note('reference','付款凭证／参考号')+note('notes','备注'),async f=>{await api({operation:'payment',id,orderId:f.get('orderId'),amount:cents(f.get('amount')),date:f.get('date'),reference:f.get('reference'),notes:f.get('notes')});await mount(current)})}
 function settings(){const s=data.settings;formDialog('Invoice settings · 发票信息',field('legalName','开票主体',s.legalName)+field('abn','ABN',s.abn)+field('address','开票地址',s.address)+note('email','邮箱',s.email)+note('phone','电话',s.phone)+`<label>GST<select name="gst">${[['unknown','待确认'],['no','未注册 GST'],['inclusive','已注册 GST：输入金额含 GST'],['exclusive','已注册 GST：输入金额未含 GST']].map(([v,t])=>`<option value="${v}" ${(s.gst||'unknown')===v?'selected':''}>${t}</option>`).join('')}</select></label>`+note('bank','收款信息',s.bank)+note('terms','付款条款',s.terms),async f=>{await api({operation:'settings',settings:Object.fromEntries(f)});await mount(current)})}
 function download(blob,name){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
 async function sample(){try{download(await RTInvoice.create({seller:{...data.settings},order:{buyer:current.name,description:'Court booking / 场地预订'},date:new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Melbourne'}),subtotal:0,gst:0,total:0,paid:0},null),'RT-invoice-template.pdf')}catch(e){if($('sales-message'))$('sales-message').textContent=e.message;else alert(e.message)}}
 async function issue(orderId){let inv=data.invoices.find(i=>i.order_id===orderId);if(!inv)inv=(await api({operation:'invoice',orderId})).invoice;const url='/api/invoice-file?number='+inv.number;let response=await fetch(url,{cache:'no-store'});let blob;if(response.ok)blob=await response.blob();else if(response.status===404){blob=await RTInvoice.create(JSON.parse(inv.snapshot),inv.number);response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/pdf'},body:blob});if(!response.ok)throw Error((await response.json()).error)}else throw Error((await response.json()).error);download(blob,'RT-'+String(inv.number).padStart(6,'0')+'.pdf')}
 function profile(l){if(!RTCRM.canEdit){location.href=signIn();return}const p=RTCRM.profile(l.id)||{};formDialog('编辑线索 / Edit lead',field('name','名称',p.name||l.name)+note('address','地址',p.address??l.address)+note('phone','电话',p.phone??l.phones?.[0])+note('email','邮箱',p.email??l.emails?.[0])+note('website','官网',p.website??RTCRM.routes(l)[4].url)+note('summaryZh','机构介绍',p.summaryZh??l.profile_summary?.[0]?.body.zh)+note('summaryEn','Organisation overview',p.summaryEn??l.profile_summary?.[0]?.body.en),async f=>{await RTCRM.saveProfile(l.id,Object.fromEntries(f));detailDirty=false;render();openDetail(l.id)})}
 async function globalInvoice(mode){if(!RTCRM.canEdit){location.href=signIn();return}current={id:'',name:'Example client / 示例客户'};const r=await fetch('/api/commerce?lead=',{cache:'no-store'});data=await r.json();if(!r.ok){alert(data.error);return}mode==='sample'?sample():settings()}
 return {globalInvoice,mount,order,payment,profile,signIn,formDialog};
})();
